<?php
namespace App\Http\Controllers;
use App\Models\Quotation; use App\Models\Invoice; use Illuminate\Http\Request;
class QuotationController extends CrudController {protected string $model=Quotation::class; protected array $rules=['customer_id'=>'required|string','customer_name'=>'nullable|string','status'=>'nullable|string','items'=>'required|array|min:1','discount'=>'nullable|numeric|min:0','tax'=>'nullable|numeric|min:0','valid_until'=>'nullable|date']; protected function searchColumns():array{return ['quotation_no','customer_id','customer_name','status'];} public function store(Request $r){$d=$r->validate($this->rules);$n=Quotation::count()+1;$d['quotation_no']='HFL-QTN-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$d=$this->totals($d);$q=Quotation::create($d);return $this->ok($q,'Created');} public function accept($id){$q=Quotation::findOrFail($id);$q->update(['status'=>'Accepted']);$n=Invoice::count()+1;$items=$q->items??[];$d=['invoice_no'=>'HFL-INV-'.str_pad((string)$n,6,'0',STR_PAD_LEFT),'quotation_id'=>$q->id,'customer_id'=>$q->customer_id,'customer_name'=>$q->customer_name,'status'=>'Unpaid','items'=>$items,'subtotal'=>$q->subtotal,'discount'=>$q->discount,'tax'=>$q->tax,'grand_total'=>$q->grand_total,'paid_amount'=>0,'outstanding'=>$q->grand_total];$inv=Invoice::create($d);return $this->ok(['quotation'=>$q,'invoice'=>$inv],'Quotation accepted and invoice created');} private function totals(array $d){$subtotal=collect($d['items']??[])->sum(fn($x)=>(float)($x['amount']??0));$discount=min($subtotal,(float)($d['discount']??0));$tax=max(0,(float)($d['tax']??0));$d['subtotal']=$subtotal;$d['discount']=$discount;$d['tax']=$tax;$d['grand_total']=max(0,$subtotal-$discount+$tax);return $d;}}
